            for(var n=0;n<200&&browser.Current!.CoreWebView2.DocumentTitle!="Submitted";n++)await Task.Delay(20);browser.Navigate($"http://127.0.0.1:{port}/");for(var n=0;n<200&&browser.Current!.CoreWebView2.DocumentTitle!="Form fixture";n++)await Task.Delay(20);elements=await Elements();var click=elements.Single(e=>e.GetProperty("label").GetString()=="Test click").GetProperty("id").GetString()!;var clickPlan=await browser.PreviewAgentAction("click",click,"");await browser.ApplyAgentAction(clickPlan,true);for(var n=0;n<100&&browser.Current!.CoreWebView2.DocumentTitle!="Clicked";n++)await Task.Delay(20);rows["browserApprovedClickRunsObservedElement"]=browser.Current!.CoreWebView2.DocumentTitle=="Clicked";
            try{await browser.PreviewAgentAction("fill","made-up-id","text");rows["browserRejectsInventedElementIds"]=false;}catch(IOException){rows["browserRejectsInventedElementIds"]=true;}
        }
        finally{browser?.Close();agentBrowser=null;stop.Cancel();listener.Close();await serving;}
    }
}
internal static class AgentFeatureTests
{
    internal static async Task Run(string output)
    {
        var rows=new Dictionary<string,object>();var root=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(output))!,"features-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);MainWindow? window=null;
        try{window=new MainWindow(["--ui-session",Path.Combine(root,"session.json")]);window.Show();await window.RunAgentFeatureTests(rows,root);}catch(Exception e){rows["error"]=e.ToString();}finally{window?.Close();}
        File.WriteAllText(output,JsonSerializer.Serialize(rows,new JsonSerializerOptions{WriteIndented=true}));Application.Current.Shutdown(rows.Values.All(v=>v is true)?0:1);
    }
}
